// 8. Verwendung 2026-08-23 (Nachschau zu einer Matrix-Meldung ueber P2's Gateway-Timeout):
// 2026/257 (vol_10821, seit 2026-08-17) und 2026/207-01 (vol_10836, seit 2026-08-21) standen
// auf contentStage='error', obwohl beide bereits echte, live veroeffentlichte WordPress-Posts
// haben (wordpressPosted=true, gueltige wordpressPostId/-Link) - reiner Stage/Payload-
// Widerspruch, kein inhaltliches Problem. Analog zum vol_10607-Fall unten (7. Verwendung):
// direkt auf 'content_posted' gesetzt statt eine Agenten-Kette erneut laufen zu lassen, die
// echte Arbeit ist schon erledigt. sharepicNeedStage/imageStage bewusst NICHT angefasst -
// vol_10821s 'blocked_content_error' bleibt als kleiner kosmetischer Rest stehen, um keinen
// neuen (kostenpflichtigen) Bildlauf fuer laengst veroeffentlichten Altcontent auszuloesen.
const TARGETS = [
  { vorgangKey: 'vol_10821', vorgangsnummer: '2026/257', targetStage: 'content_posted' },
  { vorgangKey: 'vol_10836', vorgangsnummer: '2026/207-01', targetStage: 'content_posted' }
];

if (!TARGETS.length) {
  throw new Error('[ContentStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    contentStage: t.targetStage || 'needs_summary',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
